/// `none` < `read` < `write`. An unknown string sorts as `none` — the safe direction: an unreadable
/// tier can then never be the thing that lets a widening through.
pub(crate) fn tier_rank(tier: &str) -> u8 {
    match tier {
        "write" => 2,
        "read" => 1,
        _ => 0,
    }
}
